mapper.select:
SELECT trace_id, user_id, algorithm, event_type, item_position
FROM feed_event
WHERE created_at >= #{since}
  AND item_position <= #{k}
ORDER BY trace_id, user_id, item_position

SELECT id, user_id, created_at, candidate_snapshot
FROM ai_feed_log
WHERE created_at >= #{since}
  AND candidate_snapshot IS NOT NULL
ORDER BY id DESC
LIMIT #{limit}

SELECT id, build_id, product_id, created_at FROM feed_event WHERE event_type = 'CLICK' AND created_at >= #{since} AND build_id IN
#{buildId}
ORDER BY id
